INSERT INTO public.perfiles_estudiante (perfil_id, usuario_id, carrera_id, facultad_id, semestre, universidad, resumen_experiencia, intereses, curriculum_url, creado_en, actualizado_en, calculando_nlp) VALUES (8, 12, 3, 2, '8', 'Universidad de Guayaquil', 'Experiencia teórica y práctica en optimización de procesos mediante simuladores. Conocimiento en Lean Manufacturing.', 'Gestión de calidad, Mejora continua, Logística.', NULL, '2026-06-03 23:07:05', '2026-06-03 23:07:05', false);
