INSERT INTO public.perfiles_estudiante (perfil_id, usuario_id, carrera_id, facultad_id, semestre, universidad, resumen_experiencia, intereses, curriculum_url, creado_en, actualizado_en, calculando_nlp) VALUES (2, 6, 1, 1, '9', 'Universidad de Guayaquil', E'Cuento con experiencia en la creación y mejora de aplicaciones web, con un fuerte enfoque en la implementación de interfaces gráficas, corrección de errores y el desarrollo de nuevas funcionalidades utilizando React, HTML, CSS y JavaScript. Manejo el control de versiones con Git y GitHub, y tengo conocimientos prácticos en el consumo de APIs REST y manejo de angular experimentado, me especializo en backend, se SQL y tambien se trabajr en node.js, tabaje en sistemas POO y buen analista\n\n.', 'Desarrollo Web, Ciencia de Datos, backend, IA', NULL, '2026-06-03 23:07:05', '2026-07-27 14:33:21', false);
INSERT INTO public.perfiles_estudiante (perfil_id, usuario_id, carrera_id, facultad_id, semestre, universidad, resumen_experiencia, intereses, curriculum_url, creado_en, actualizado_en, calculando_nlp) VALUES (1, 5, 1, 1, '9', 'Universidad de Guayaquil', 'Me especializo en el análisis profundo de información y la creación de sistemas inteligentes. Además de mi enfoque en algoritmos de aprendizaje automático, cuento con vasta experiencia en desarrollo de aplicaciones móviles multiplataforma usando Flutter, así como diseño de interfaces frontend con React y Tailwind CSS. ademas manejo agnetes de IA en diferentes modelos, con portocolos MCP y python ', 'Redes neuronales, Análisis estadístico, Desarrollo Frontend', NULL, '2026-06-03 23:07:05', '2026-06-24 00:13:06', false);
INSERT INTO public.perfiles_estudiante (perfil_id, usuario_id, carrera_id, facultad_id, semestre, universidad, resumen_experiencia, intereses, curriculum_url, creado_en, actualizado_en, calculando_nlp) VALUES (7, 11, 2, 1, '9', 'Universidad de Guayaquil', 'Entusiasta de los datos. He participado en hackathons de análisis predictivo. Manejo de Python, Pandas y Scikit-Learn.', 'Inteligencia Artificial, Machine Learning, Análisis predictivo.', NULL, '2026-06-03 23:07:05', '2026-06-03 23:07:05', false);
