INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (26, 1, 1, 'Desarrollo de Software Móvil y Servicios Web', 'Desarrollo Móvil', 'Participación en la construcción de soluciones para dispositivos celulares y tablets. Las actividades principales involucran el consumo de APIs, la estructuración de interfaces de usuario ágiles y la persistencia de información en sistemas relacionales del lado del servidor.', 'Se requiere destreza armando pantallas interactivas multiplataforma. Nociones sólidas en la creación de endpoints y administración de tablas de datos. Interés por la experiencia de usuario (UX) y el rendimiento en la nube.', 'Híbrido', 'Guayaquil', 144, 6, 'Lunes a Viernes', 1, false, '2026-07-11 00:00:00', '2026-06-20 10:45:04', '2026-06-22 00:04:03');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (18, 2, 2, 'Data Scientist / Ingeniero Machine Learning', 'Tecnología', 'Buscamos un estudiante de la carrera de Software con interés en Ciencia de Datos, Machine Learning e Inteligencia Artificial para apoyar en el desarrollo de proyectos de análisis de datos y modelos predictivos. El candidato participará en el procesamiento, limpieza y análisis de grandes volúmenes de información utilizando Python, Pandas y Scikit-Learn, contribuyendo a la optimización de procesos mediante soluciones basadas en datos. Se valorará la capacidad analítica, el aprendizaje continuo y el interés por desarrollar modelos de machine learning aplicados a problemas reales.', E'Estudiante de la carrera de Software.\nConocimientos en Inteligencia Artificial.\nConocimientos en Machine Learning.\nConocimientos en Ciencia de Datos (Data Science).\nManejo de Python.\nExperiencia académica utilizando Pandas.\nConocimientos en Scikit-Learn.\nConocimientos en análisis y procesamiento de datos.\nInterés en el desarrollo de modelos predictivos.\nCapacidad analítica para la optimización de procesos.', 'Remoto', 'Guayaquil', 240, 6, 'Matutino', 2, true, '2026-07-17 00:00:00', '2026-06-11 23:51:57', '2026-07-09 00:16:23');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (10, 10, 10, 'Asistente de Desarrollo Frontend', 'Desarrollo web', 'Buscamos un estudiante con interés en el desarrollo web para apoyar al equipo en la creación y mejora de aplicaciones internas en frontend. Durante las prácticas participará en tareas de implementación de interfaces, corrección de errores y desarrollo de nuevas funcionalidades, trabajando junto a desarrolladores con experiencia.', E'- Conocimientos básicos de HTML, CSS y JavaScript.\n- Experiencia académica utilizando React.\n- Manejo básico de Git y GitHub.\n- Conocimientos de consumo de APIs REST.\n- Capacidad para trabajar en equipo y disposición para aprender.\n- Conocimiento en angular.', 'Presencial', 'Daule', 144, 5, 'Lunes a Viernes', 10, true, '2026-09-19 00:00:00', '2026-06-03 23:07:05', '2026-07-21 13:27:51');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (1, 1, 1, 'Desarrollador Backend Python & Microservicios', 'Tecnología y Software', 'Buscamos un practicante apasionado por el desarrollo backend en Python para colaborar en la construcción de microservicios escalables con Flask/FastAPI, integración de APIs RESTful y optimización de consultas SQL en PostgreSQL.', E'- Estudiante de 6to semestre en adelante de Ing. en Software o Sistemas.\n- Manejo fluido de Python y principios de Programación Orientada a Objetos.\n- Conocimiento en diseño de API REST y manejo de Git.\n- Deseable experiencia básica con Flask o Django.', 'Híbrido', 'Guayaquil', 240, 6, 'Lunes a Viernes 08:00 a 14:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (2, 2, 2, 'Desarrollador Java & Arquitectura Enterprise', 'Desarrollo de Software', 'Únete al equipo de desarrollo institucional para participar en la modernización de plataformas empresariales construidas sobre Java Spring Boot. Trabajarás con patrones de diseño, pruebas unitarias y gestión de bases de datos relacionales.', E'- Estudiante de últimos semestres de Ing. en Software o Ciencias de la Computación.\n- Sólidas bases de arquitectura Java (Spring Boot / Maven / Gradle).\n- Experiencia en bases de datos relacionales y sentencias SQL complejas.\n- Buenas prácticas de código limpio y control de versiones.', 'Presencial', 'Guayaquil', 240, 6, 'Lunes a Viernes 08:30 a 14:30', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (3, 3, 3, 'Desarrollador Node.js & Servicios en la Nube', 'Desarrollo Web & Cloud', 'Oportunidad de práctica para desarrolladores con interés en JavaScript/TypeScript backend. Participarás en la creación de APIs asíncronas de alto rendimiento con Node.js/Express e integración con servicios cloud.', E'- Estudiante universitario de Software, Sistemas o carreras afines.\n- Dominio de JavaScript / TypeScript moderno (ES6+).\n- Conocimientos de Node.js, Express y conexión a bases de datos NoSQL/SQL.\n- Interés en entornos cloud (AWS o Google Cloud).', 'Remoto', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 3, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (7, 7, 7, 'Desarrollador Full Stack (Énfasis en Backend)', 'Desarrollo Web', 'Apoyo en el desarrollo integral de aplicaciones corporativas. Diseñarás lógica de servidor segura e integrarás componentes frontend dinámicos con React y servicios API REST.', E'- Estudiante de 7mo semestre en adelante de Ing. en Software.\n- Manejo de JavaScript / TypeScript tanto en cliente como en servidor.\n- Experiencia básica en React/Vue y Node.js/Python.\n- Manejo de Git y herramientas de testing.', 'Híbrido', 'Guayaquil', 240, 6, 'Lunes a Viernes 08:00 a 14:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (4, 4, 4, 'Desarrollador C# .NET Core & Servicios Web', 'Desarrollo Backend', 'Buscamos estudiante interesado en la plataforma Microsoft .NET Core. Te integrarás en proyectos corporativos para desarrollar Web APIs, conectar modelos ORM (Entity Framework) y aplicar pruebas de integración.', E'- Conocimiento en lenguajes C# y sintaxis de .NET Framework / Core.\n- Manejo de Entity Framework o controladores SQL Server / PostgreSQL.\n- Comprensión de conceptos de POO y capas de software.\n- Capacidad de trabajo colaborativo en equipos ágiles.', 'Híbrido', 'Guayaquil', 240, 6, 'Lunes a Viernes 08:00 a 14:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (17, 1, 1, 'Análisis de Datos y Desarrollo Web', 'Sistemas', 'Buscamos un estudiante de Ingeniería en Software o carreras afines para apoyar en el análisis de datos y el desarrollo de soluciones web internas. El practicante participará en la limpieza y procesamiento de datos, generación de reportes, automatización de tareas mediante scripts y apoyo en el desarrollo de módulos web utilizando tecnologías frontend y backend. Tendrá la oportunidad de trabajar con datos reales y colaborar con equipos multidisciplinarios en proyectos tecnológicos.', E'Requisitos en texto\nEstudiante de Ingeniería en Software, Sistemas o carreras afines (5to semestre en adelante).\nConocimientos de Python para análisis y procesamiento de datos.\nManejo básico de Pandas y NumPy.\nConocimientos de estadística descriptiva.\nConocimientos de JavaScript para desarrollo web.\nCapacidad para interpretar y visualizar información.\nConocimientos básicos de bases de datos relacionales.\nHabilidades de comunicación y trabajo en equipo.\nDeseable experiencia académica en proyectos de análisis de datos o desarrollo web.', 'Remoto', 'Guayaquil', 144, 6, 'Lunes a Viernes', 4, false, '2026-06-28 00:00:00', '2026-06-11 23:02:24', '2026-06-15 21:51:20');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (6, 6, 6, 'Desarrollador Go / Golang & Sistemas Concurrentes', 'Software e Infraestructura', 'Buscamos pasante enfocado en rendimiento y sistemas de alta velocidad. Trabajarás con lenguaje Go desarrollando servicios distribuidos, APIs de respuesta ultra rápida y contenedores Docker.', E'- Estudiante de Software o Ciencias de la Computación.\n- Interés o experiencia académica programando en Go (Golang) o C/C++.\n- Nociones de concurrencia (goroutines, channels) y redes TCP/HTTP.\n- Manejo de entornos Linux y Docker.', 'Híbrido', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (8, 8, 8, 'Ingeniero Backend & Seguridad de APIs', 'Ciberseguridad y Backend', 'Práctica profesional enfocada en la protección y optimización de endpoints backend. Implementación de protocolos de autenticación (OAuth2, JWT), encriptación y auditoría de peticiones HTTP.', E'- Estudiante de Software, Ciberseguridad o Sistemas.\n- Conocimientos sobre protocolos de seguridad web y JWT/OAuth.\n- Experiencia programando backend en Python, Node.js o Java.\n- Pensamiento lógico enfocado en prevención de vulnerabilidades.', 'Remoto', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (11, 11, 11, 'Analista de Business Intelligence (BI) & Reportes', 'Ciencia de Datos & BI', 'Apoyo en el diseño de tableros ejecutivos interactivos utilizando Power BI y SQL. Trabajarás transformando datos crudos en métricas e indicadores de rendimiento claves (KPIs) para la gerencia.', E'- Estudiante de Ciencia de Datos, Software o Ing. Industrial.\n- Dominio de herramientas BI (Power BI, Tableau) y lenguaje DAX.\n- Manejo fluido de SQL y estructuración de modelos dimensionales.\n- Habilidades de comunicación y presentación visual de datos.', 'Remoto', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (12, 12, 12, 'Analista de Big Data & Pipelines ETL', 'Ingeniería de Datos', 'Buscamos pasante apasionado por el procesamiento de grandes volúmenes de información. Apoyarás en el diseño de pipelines ETL con Python (Pandas/PySpark) e ingesta de fuentes heterogéneas.', E'- Estudiante de Ciencia de Datos, Software o afines.\n- Manejo avanzado de Python (Pandas, NumPy) y consultas SQL.\n- Nociones de arquitecturas Data Lake y procesamiento distribuido.\n- Capacidad analítica y resolución de cuellos de botella de datos.', 'Remoto', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (14, 14, 14, 'Pasante de Lean Manufacturing & Mejora Continua', 'Ingeniería de la Producción', 'Buscamos estudiante de Ing. en Producción para colaborar en la optimización de líneas de ensamble, aplicación de metodologías 5S, Kaizen y mapeo de flujo de valor (VSM).', E'- Estudiante de 7mo semestre en adelante de Ing. de la Producción o Industrial.\n- Conocimientos teóricos de metodologías Lean Manufacturing y Six Sigma.\n- Manejo avanzado de Excel y herramientas estadísticas.\n- Proactividad y liderazgo en planta.', 'Presencial', 'Durán', 240, 6, 'Lunes a Viernes 07:00 a 13:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (15, 15, 15, 'Pasante de Automatización de Procesos Operativos', 'Producción & Operaciones', 'Práctica profesional orientada a la digitalización y automatización de flujo de materiales y control de inventarios. Participarás en la estandarización de procesos y reducción de desperdicios.', E'- Estudiante de Ing. en Producción o carreras industriales.\n- Interés en tecnologías de automatización y gestión logística.\n- Dominio de herramientas informáticas de gestión de procesos.\n- Habilidad de análisis de tiempos y movimientos.', 'Presencial', 'Durán', 240, 6, 'Lunes a Viernes 07:00 a 13:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (16, 1, 1, 'Administrador de Redes & Infraestructura de Telecom', 'Redes y Telecomunicaciones', 'Práctica en gestión y soporte de infraestructura de comunicaciones de red. Configuración de routers, switches, reglas de firewall y monitoreo de tráfico institucional.', E'- Estudiante de Telecomunicaciones, Redes o Sistemas.\n- Conocimientos de modelo OSI, TCP/IP y direccionamiento IPv4/IPv6.\n- Manejo básico de equipos Cisco o MikroTik.\n- Disposición para trabajo técnico en campo y configuración remota.', 'Presencial', 'Guayaquil', 144, 6, 'Lunes a Viernes 08:00 a 14:00', 2, true, '2026-07-03 00:00:00', '2026-06-04 18:36:44', '2026-06-12 00:11:28');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (24, 2, 2, 'Practicas en Desarrollo de Software Multiplataforma', 'Desarrollo', 'Apoyo en el desarrollo de aplicaciones. Tareas orientadas a la integracion de interfaces frontend y manipulacion de bases de datos con SQL y pyhton para el backend.', 'Manejo de pyhton, SQL y Data Analysis. Uso de Adobe XD para diseno de interfaces.', 'Presencial', 'Quito', 160, 6, 'Lunes a Viernes 09:00 a 15:00', 1, true, '2027-12-31 00:00:00', '2026-06-16 22:47:55', '2026-06-16 22:47:55');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (23, 2, 2, 'Practicas en Data Science e IA', 'Tecnología', 'Participacion en el analisis profundo de informacion y creacion de sistemas inteligentes. Apoyo en el entrenamiento de redes neuronales y algoritmos de aprendizaje automatico para extraer valor de los datos.', 'Conocimiento en Data Science y Machine Learning. Manejo de pyhton y SQL. Interes en analisis estadistico y modelos de IA avanzados.', 'Remoto', 'Guayaquil', 160, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-16 22:47:55', '2026-06-16 22:47:55');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (5, 5, 5, 'Desarrollador Backend PHP & Framework Laravel', 'Sistemas de Información', 'Participa en el mantenimiento evolutivo y creación de nuevos módulos web utilizando PHP 8 y Laravel. Apoyarás en el diseño de arquitectura MVC, migraciones de base de datos e integración con paneles administrativos.', E'- Estudiante de 6to semestre en adelante en Software/Sistemas.\n- Manejo básico o intermedio de PHP y POO.\n- Nociones de desarrollo web con Laravel o frameworks MVC.\n- Manejo de motores de base de datos MySQL o PostgreSQL.', 'Presencial', 'Samborondón', 240, 6, 'Lunes a Viernes 08:30 a 14:30', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (9, 9, 9, 'Desarrollador de Integraciones Backend & ERP', 'Sistemas Empresariales', 'Participa en la interconexión de sistemas ERP y bases de datos transaccionales de la empresa. Desarrollarás pipelines de sincronización de datos y webhooks para automatizar procesos financieros y operativos.', E'- Estudiante de últimos semestres de Ing. en Software o Sistemas.\n- Sólido manejo de SQL (procedimientos almacenados, triggers, vistas).\n- Experiencia en lenguaje backend (Python, C# o Java).\n- Orientación al orden y estructura de datos empresarial.', 'Presencial', 'Guayaquil', 240, 6, 'Lunes a Viernes 08:00 a 14:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (13, 13, 13, 'Analista Estadístico & Modelación de Métricas', 'Ciencia de Datos', 'Únete al equipo analítico para realizar análisis exploratorio de datos (EDA), pruebas de hipótesis estadísticas y construcción de modelos predictivos básicos para optimización del negocio.', E'- Estudiante de Ciencia de Datos, Estadística o Software.\n- Sólidas bases de estadística descriptiva e inferencial.\n- Manejo de Python o R para análisis estadístico.\n- Capacidad de documentación y elaboración de conclusiones fundamentadas.', 'Remoto', 'Guayaquil', 240, 6, 'Lunes a Viernes 09:00 a 15:00', 2, true, '2027-12-31 00:00:00', '2026-06-03 23:07:05', '2026-06-03 23:07:05');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (25, 2, 2, 'Practicas en Ingenieria de Datos y Backend', 'Backend', 'Desarrollo de pipelines de datos y microservicios orientados al analisis de informacion en el ecosistema Microsoft. Apoyo en la arquitectura de software.', 'Conocimientos en .NET y bases de datos relacionales como SQL. Interes en la implementacion de algoritmos.', 'Híbrido', 'Cuenca', 160, 6, 'Lunes a Viernes 09:00 a 15:00', 3, true, '2027-12-31 00:00:00', '2026-06-16 22:47:55', '2026-06-16 22:47:55');
